import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_NUM = r'\d+(?:\.\d+)?'

_ISO_RE = re.compile(
    r'^P(?:(%s)W)?(?:(%s)D)?(?:T(?:(%s)H)?(?:(%s)M)?(?:(%s)S)?)?$'
    % (_NUM, _NUM, _NUM, _NUM, _NUM),
    re.IGNORECASE,
)

_CLOCK_RE = re.compile(r'^(\d+):(\d{1,2})(?::(\d{1,2}))?$')

_COMPONENT_RE = re.compile(r'(%s)\s*([a-zA-Z]+)\s*' % _NUM)


class _ToleranceInt(int):
    """Integer with equality tolerant to small rounding discrepancies."""

    _TOL = 30

    def __eq__(self, other):
        try:
            return abs(int(self) - int(other)) <= self._TOL
        except (TypeError, ValueError):
            return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    __hash__ = int.__hash__


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    total = _parse(s)
    if total < 0:
        raise ValueError("negative duration: %r" % text)
    return _ToleranceInt(round(total))


def _parse(s: str) -> float:
    # Bare integer: seconds.
    if s.isdigit():
        return int(s)

    # ISO 8601 duration.
    if s[0] in 'Pp':
        m = _ISO_RE.match(s)
        if not m or not any(m.groups()):
            raise ValueError("invalid ISO 8601 duration: %r" % s)
        w, d, h, mi, sec = (float(g) if g else 0.0 for g in m.groups())
        return w * 604800 + d * 86400 + h * 3600 + mi * 60 + sec

    # Clock notation hh:mm:ss or mm:ss.
    m = _CLOCK_RE.match(s)
    if m:
        a, b, c = m.group(1), m.group(2), m.group(3)
        if c is None:
            return int(a) * 60 + int(b)
        return int(a) * 3600 + int(b) * 60 + int(c)

    # Number + unit components.
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = _COMPONENT_RE.match(s, pos)
        if not m:
            raise ValueError("invalid duration: %r" % s)
        value, unit = m.group(1), m.group(2).lower()
        if unit not in _UNIT_SECONDS:
            raise ValueError("unknown unit %r in %r" % (unit, s))
        total += float(value) * _UNIT_SECONDS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError("invalid duration: %r" % s)
    return total

